import unittest
from candidate import monotonic

class TestMonotonic(unittest.TestCase):
    def test_empty_list_true(self):
        self.assertTrue(monotonic([]))

    def test_single_element_true(self):
        self.assertTrue(monotonic([42]))

    def test_ascending_order_true(self):
        self.assertTrue(monotonic([1, 2, 3, 4, 5]))

    def test_descending_order_true(self):
        self.assertTrue(monotonic([5, 4, 3, 2, 1]))

    def test_non_monotonic_false(self):
        self.assertFalse(monotonic([1, 3, 2, 4]))

    def test_duplicate_elements_true(self):
        self.assertTrue(monotonic([1, 2, 2, 3, 3]))

    def test_floats_ascending_true(self):
        self.assertTrue(monotonic([0.1, 0.2, 0.3, 0.4]))

    def test_floats_descending_true(self):
        self.assertTrue(monotonic([0.4, 0.3, 0.2, 0.1]))

    def test_mixed_comparable_types_true(self):
        self.assertTrue(monotonic([1, 2.0, 3, 4.0]))

    def test_mixed_comparable_types_descending_true(self):
        self.assertTrue(monotonic([4.0, 3, 2.0, 1]))

    def test_mixed_incomparable_types_raises_type_error(self):
        with self.assertRaises(TypeError):
            monotonic([1, 'a', 3])

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            monotonic(None)

    def test_integer_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            monotonic(42)

    def test_string_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            monotonic("123")

    def test_tuple_input_false(self):
        self.assertFalse(monotonic((5, 4, 3, 2, 1)))

    def test_negative_and_positive_ascending_true(self):
        self.assertTrue(monotonic([-5, -3, -1, 0, 2, 4]))

    def test_negative_and_positive_descending_true(self):
        self.assertTrue(monotonic([4, 2, 0, -1, -3, -5]))

    def test_non_monotonic_with_negative_and_positive_false(self):
        self.assertFalse(monotonic([-5, -3, 2, 1, 4]))

if __name__ == "__main__":
    unittest.main()
